const int gridSize = 1000000;
const int gridWrap = gridSize - 1;

auto calculateHash = [h, gridSize, gridWrap](float x, float y, float z) -> size_t {
    int ix = static_cast<int>(x / h) & gridWrap;
    int iy = static_cast<int>(y / h) & gridWrap;
    int iz = static_cast<int>(z / h) & gridWrap;
    return ix + gridSize * (iy + gridSize * iz);
};

std::for_each(std::execution::par_unseq, particles + start, particles + end,
    [calculateHash, h](Particle& p) {
        p.hash = calculateHash(p.position.x, p.position.y, p.position.z);
    });
// END_CODE

